const h=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
// General comparison prompts, not an assertion that a CIP category offers every award.
export const educationRoutes=[
 {id:'certificate',title:'College certificate',focus:'A focused set of courses or practical training.',check:'What exact skills and award does it cover? Can credits count toward another award? What further requirements remain?'},
 {id:'associate',title:'Associate / transfer',focus:'Compare a technical or workforce program with a transfer-oriented foundation.',check:'Which courses transfer to the named bachelor’s program? Which prepare for a specific role? Get the actual agreement and sequence.'},
 {id:'bachelor',title:'Bachelor’s',focus:'Compare first-year foundations, later subject depth and practical experience.',check:'Which prerequisites, transfer credits, placements and accreditation apply? What is the full course sequence and net price?'},
 {id:'graduate',title:'Later graduate / professional study',focus:'Advanced subject study or professional preparation after its required earlier study.',check:'What prior degree, admissions, licensing or experience is required? Keep later tuition, time and earnings separate.'}
];
export function routeComparison(p,answer={},compact=false){const focus=educationRoutes.find(r=>r.id===answer?.route);return`<section class="panel route-comparison" aria-label="Compare education routes for ${h(p.title)}"><h${compact?'3':'2'}>Compare the college beginnings</h${compact?'3':'2'}><p><strong>Pathway context:</strong> ${h(p.route)}</p>${focus?`<p class="intent-badge">Your first comparison: ${h(focus.title)}. Other routes remain open.</p>`:''}<p>These are routes to investigate, not confirmed awards offered by every program in this pathway. A program category alone does not establish its credential level, duration, price, transferability or eligibility.</p>${compact?`<div class="route-cards">${educationRoutes.map(r=>`<article class="route-choice${focus?.id===r.id?' route-focus':''}"><h4>${h(r.title)}${focus?.id===r.id?' · your first comparison':''}</h4><p>${h(r.focus)}</p><p><strong>Check with the program:</strong> ${h(r.check)}</p></article>`).join('')}</div>`:`<div class="route-table-scroll"><table><caption>Education routes · questions to take to a named college program</caption><thead><tr><th scope="col">Route</th><th scope="col">What to compare</th><th scope="col">What needs verification</th></tr></thead><tbody>${educationRoutes.map(r=>`<tr${focus?.id===r.id?' class="route-focus"':''}><th scope="row">${h(r.title)}${focus?.id===r.id?' · your first comparison':''}</th><td>${h(r.focus)}</td><td>${h(r.check)}</td></tr>`).join('')}</tbody></table></div>`}<p class="note">${h(p.caution)}</p><p class="subtle">Certificates, engineering technology, engineering degrees and professional qualifications are not interchangeable. Confirm the actual sequence before comparing time, cost or earning examples.</p></section>`;}
